--- a/lib/chat/sheet.dart
+++ b/lib/chat/sheet.dart
@@ -12,6 +12,16 @@ class ChatSheet extends ConsumerStatefulWidget {
   void initState() {
     super.initState();
     WidgetsBinding.instance.addPostFrameCallback((_) {
+      // resume any requested thread; legacy null-course threads
+      // resume into the selected course (PR promise)
+      // consume the resume target only once a course exists:
+      // CourseSelector auto-selects in a later frame; reacting
+      // here would drop legacy null-course resumes.
+      ref.listenManual(chatCourseIdProvider, (prev, course) {
+        final target = ref.read(chatResumeTargetProvider);
+        if (target == null || course == null) return;
+        ref.read(chatResumeTargetProvider.notifier).state = null;
+        _resume(target.threadId, course);
+      });
       _restoreOrResume();
     });
   }
